-- SQLite: ID는 NULL이 될 수 없는 실제 요청 식별자입니다.
CREATE TABLE building(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE request(id INTEGER PRIMARY KEY, building TEXT NOT NULL, status TEXT NOT NULL);
INSERT INTO building VALUES ('A'),('B');
INSERT INTO request VALUES (1,'A','open'),(2,'A','closed'),(3,'A','open');
SELECT b.id, COUNT(r.id) AS open_count FROM building AS b
LEFT JOIN request AS r ON r.building=b.id AND r.status='open'
GROUP BY b.id ORDER BY b.id;
